class Animal {
    protected final String name;

    Animal(String name) {
        this.name = name;
    }

    String sound() {
        return "...";
    }

    void introduce() {
        System.out.println(name + " says " + sound());
    }
}

class Dog extends Animal {
    Dog(String name) {
        super(name);
    }

    @Override
    String sound() {
        return "Woof";
    }
}

class Cat extends Animal {
    Cat(String name) {
        super(name);
    }

    @Override
    String sound() {
        return "Meow";
    }
}

public class Main {
    public static void main(String[] args) {
        Animal[] animals = { new Dog("Rex"), new Cat("Tom"), new Animal("Generic") };
        for (Animal animal : animals) {
            animal.introduce();
        }
    }
}

abstract class Employee {
    private final String name;

    Employee(String name) {
        this.name = name;
    }

    abstract double monthlyPay();

    String payslip() {
        return name + ": " + monthlyPay();
    }
}

class Salaried extends Employee {
    private final double annualSalary;

    Salaried(String name, double annualSalary) {
        super(name);
        this.annualSalary = annualSalary;
    }

    @Override
    double monthlyPay() {
        return annualSalary / 12;
    }
}

class Hourly extends Employee {
    private final double rate;
    private final int hours;

    Hourly(String name, double rate, int hours) {
        super(name);
        this.rate = rate;
        this.hours = hours;
    }

    @Override
    double monthlyPay() {
        return rate * hours;
    }
}

public class Payroll {
    public static void main(String[] args) {
        Employee[] staff = { new Salaried("Ada", 60000), new Hourly("Bob", 25, 160) };
        for (Employee employee : staff) {
            System.out.println(employee.payslip());
        }
    }
}

interface Shape {
    double area();

    default String describe() {
        return String.format("%s with area %.2f", getClass().getSimpleName(), area());
    }
}

class Rectangle implements Shape {
    private final double width;
    private final double height;

    Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    public double area() {
        return width * height;
    }
}

class Circle implements Shape {
    private final double radius;

    Circle(double radius) {
        this.radius = radius;
    }

    public double area() {
        return Math.PI * radius * radius;
    }
}

public class Shapes {
    public static void main(String[] args) {
        Shape[] shapes = { new Rectangle(3, 4), new Circle(1) };
        double total = 0;
        for (Shape shape : shapes) {
            System.out.println(shape.describe());
            total += shape.area();
        }
        System.out.printf("Total area: %.2f%n", total);
    }
}

